import sys
import subprocess

def check_user(username):
    try:
        # Запускаем команду id с именем пользователя
        result = subprocess.run(['id', username], capture_output=True, text=True, check=False)

        # Выводим статус завершения
        print(f"Статус завершения: {result.returncode}")

        # Проверяем, был ли пользователь найден
        if result.returncode == 0:
            print("Пользователь найден")
        else:
            print("Пользователь не найден")

    except Exception as e:
        print(f"Ошибка при выполнении команды: {e}")

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Использование: python script.py <имя_пользователя>")
        sys.exit(1)

    username = sys.argv[1]
    check_user(username)

